//
//  Ray Tracing (Reflections, Refractions, Caustics)
//  Native Metal Shader - Path Tracing
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float reflection_strength;
    float refraction_index;
    float caustics_strength;
    float samples;
    float sphere_count;     // 1..16
    float radius_min;       // 0.05..0.6
    float radius_max;       // 0.05..0.8
    float anim_speed;       // 0..2
    float anim_scale;       // 0..1
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut vertex_main(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Sphere SDF
float sdSphere(float3 p, float3 center, float radius) {
    return length(p - center) - radius;
}

// Pseudo-random
float hash11(float x){ return fract(sin(x*12.9898)*43758.5453); }
float2 hash21(float x){ float n = sin(x*78.233); return fract(float2(262144.0*n, 32768.0*n)); }

// Scene SDF with animated spheres
float sceneSDF(float3 p, constant Uniforms &u, float time) {
    int N = int(clamp(round(u.sphere_count), 1.0, 16.0));
    float dmin = 1e9;
    for (int i=0;i<N;++i){
        float fi = float(i);
        float2 h = hash21(fi+13.0);
        float ang = h.x * 6.28318 + time * u.anim_speed * (0.5 + h.y);
        float rad = mix(u.radius_min, u.radius_max, hash11(fi+7.0));
        float r  = 0.6 + 0.3 * u.anim_scale * sin(time*0.7 + fi);
        float3 c = float3(r*cos(ang), 0.3*sin(ang*0.7 + fi*0.37), r*sin(ang));
        float d = sdSphere(p, c, rad);
        dmin = min(dmin, d);
    }
    return dmin;
}

// Calculate normal
float3 calcNormal(float3 p, constant Uniforms &u, float time) {
    const float eps = 0.001;
    float2 h = float2(eps, 0.0);
    return normalize(float3(
        sceneSDF(p + h.xyy, u, time) - sceneSDF(p - h.xyy, u, time),
        sceneSDF(p + h.yxy, u, time) - sceneSDF(p - h.yxy, u, time),
        sceneSDF(p + h.yyx, u, time) - sceneSDF(p - h.yyx, u, time)
    ));
}

// Fresnel effect
float fresnel(float3 I, float3 N, float ior) {
    float cosi = clamp(dot(I, N), -1.0, 1.0);
    float etai = 1.0;
    float etat = ior;

    if (cosi > 0.0) {
        float temp = etai;
        etai = etat;
        etat = temp;
    }

    float sint = etai / etat * sqrt(max(0.0, 1.0 - cosi * cosi));

    if (sint >= 1.0) {
        return 1.0; // Total internal reflection
    }

    float cost = sqrt(max(0.0, 1.0 - sint * sint));
    cosi = abs(cosi);

    float Rs = ((etat * cosi) - (etai * cost)) / ((etat * cosi) + (etai * cost));
    float Rp = ((etai * cosi) - (etat * cost)) / ((etai * cosi) + (etat * cost));

    return (Rs * Rs + Rp * Rp) / 2.0;
}

fragment float4 main0(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    float time = float(uniforms.FrameCount) * 0.01;

    // Ray setup
    float2 uv = (in.texCoord * 2.0 - 1.0);
    uv.x *= uniforms.OutputSize.x / uniforms.OutputSize.y;

    float3 ro = float3(0.0, 0.0, -2.0); // Ray origin
    float3 rd = normalize(float3(uv, 1.0)); // Ray direction

    // Ray marching
    float t = 0.0;
    bool hit = false;
    float3 hitPos;

    for (int i = 0; i < 16; i++) {
        float3 p = ro + rd * t;
        float d = sceneSDF(p, uniforms, time);

        if (d < 0.001) {
            hit = true;
            hitPos = p;
            break;
        }

        t += d;
        if (t > 10.0) break;
    }

    if (hit) {
        float3 normal = calcNormal(hitPos, uniforms, time);

        // Reflection
        float3 reflectDir = reflect(rd, normal);
        float2 reflectUV = reflectDir.xy * 0.5 + 0.5;
        float3 reflectColor = sourceTexture.sample(textureSampler, reflectUV).rgb;

        // Refraction
        float3 refractDir = refract(rd, normal, 1.0 / uniforms.refraction_index);
        float2 refractUV = refractDir.xy * 0.5 + 0.5;
        float3 refractColor = sourceTexture.sample(textureSampler, refractUV).rgb;

        // Fresnel blend
        float F = fresnel(rd, normal, uniforms.refraction_index);
        float3 finalColor = mix(refractColor, reflectColor, F);

        // Caustics (simplified)
        float caustics = sin(hitPos.x * 10.0 + time) * sin(hitPos.y * 10.0 + time * 1.3);
        caustics = pow(max(caustics, 0.0), 3.0);
        finalColor += float3(0.5, 0.8, 1.0) * caustics * uniforms.caustics_strength;

        // Mix with original
        color.rgb = mix(color.rgb, finalColor, uniforms.reflection_strength);
    }

    return color;
}

